/* PulseFit v2: shared components, route-preserving presentation, localisation and motion. */
const legacyScreens={...screens},legacyRender=render,legacyGo=go,legacyNav=nav,legacyBack=backNow,legacyAfter=afterRender;
const orb='assets/ai-orb.webp',yogaPhoto='assets/community-yoga.webp',foodPhoto='assets/food-bowl.webp';
const nf=(n,opts={})=>PF_I18N.number(n,state.lang,opts), df=(d='2026-09-18T12:00:00',opts)=>PF_I18N.date(d,state.lang,opts);
const score=()=>82+Math.min(state.workouts.length*2,16), workoutMinutes=()=>state.workouts.reduce((a,b)=>a+b.minutes,0), workoutEnergy=()=>state.workouts.reduce((a,b)=>a+b.calories,0);
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const img=(src,alt,cls='',eager=false)=>`<img src="${src}" alt="${esc(t(alt))}" class="${cls}" loading="${eager?'eager':'lazy'}" decoding="async" onload="this.classList.add('loaded')">`;
const aiOrb=(cls='')=>img(orb,'PulseFit AI glass orb',`ai-orb ${cls}`,true);
const person=(name=state.name,cls='')=>`<span class="avatar ${cls}" data-user-content>${esc(name.split(' ').map(x=>x[0]).join('').slice(0,2))}</span>`;
const badge=(label,ico='')=>`<span class="status-badge">${ico?icon(ico):''}${t(label)}</span>`;
function topHeader(title,subtitle='',actions=''){return `<header class="dashboard-header"><div>${subtitle?`<p class="eyebrow">${t(subtitle)}</p>`:''}<h1>${t(title)}</h1></div><div class="row">${actions}</div></header>`}
function wellnessRing(size=''){return `<div class="wellness-ring ${size}" style="view-transition-name:wellness-ring"><svg viewBox="0 0 180 180" aria-label="${esc(t('Wellness breakdown'))}" role="img">${['blue','health','orange','purple'].map((c,i)=>`<circle cx="90" cy="90" r="73" transform="rotate(${i*90-84} 90 90)" pathLength="100" stroke="var(--color-${c})" stroke-dasharray="21.5 78.5"/>`).join('')}</svg><div class="wellness-ring-value"><strong data-count="${score()}" style="view-transition-name:wellness-score">${nf(score())}<small>%</small></strong><span>${t('In balance')}</span></div></div>`}
function wellnessHero(detail=false){return `<section class="global-wellness ${detail?'expanded':''}" style="view-transition-name:wellness-card"><div class="row between"><div><p class="eyebrow">${t('YOUR HEALTH, CONNECTED')}</p><h2 style="view-transition-name:wellness-title">${t('Global Wellness')}</h2></div>${ib(detail?'share':'arrow',detail?"share('Daily wellness')":"go('wellness')",detail?'Share':'Wellness details')}</div><div class="wellness-stage"><button class="wellness-score-button" onclick="${detail?"go('scoreInfo')":"go('wellness')"}" aria-label="${esc(t('View wellness details'))}">${wellnessRing()}</button><div class="wellness-ai">${aiOrb()}<div class="glass ai-status">${icon('activity')}<span>${t('General well-being')}<strong>+8 ${t('pts')}</strong></span></div></div></div><div class="wellness-legend">${[['Physical Activity',80,'blue','activity'],['Recovery',85,'health','report'],['Nutrition',75,'orange','article'],['Mental Health',90,'purple','article']].map(([label,n,c,p],i)=>`<button onclick="go('${p}','${i===2?'1':i===3?'4':''}')"><i style="background:var(--color-${c})"></i><span>${t(label)}</span><strong>${nf(n)}%</strong></button>`).join('')}</div><button class="ai-link" onclick="go('aiCoach')">${icon('activity')}<span>${t('AI recommendations')}</span>${icon('arrow')}</button></section>`}
function analytics(){return `<section class="analytics-card"><div class="row between"><h3>${t('Today Analytics')}</h3>${badge('On track')}</div><div class="analytics-bars">${[['Strength',45,'accent'],['Activity',25,'health'],['Nutrition',20,'orange'],['Hydration',10,'blue']].map(([l,n,c])=>`<button onclick="go('${l==='Strength'?'plan':l==='Activity'?'activity':l==='Hydration'?'task':'article'}','${l==='Hydration'?'Hydration check-in':l==='Nutrition'?'1':''}')" aria-label="${esc(t(l))}"><span class="thin-progress" style="--data-color:var(--color-${c})"><i style="width:${n*1.4+30}%"></i></span><span>${t(l)}<b>${nf(n)}%</b></span></button>`).join('')}</div></section>`}
function miniChart(type,color){let vals=[13,20,16,29,24,34,29,42,37,45,33,52];return `<svg class="metric-chart" viewBox="0 0 130 42" aria-hidden="true">${type==='wave'?`<path d="M0 22h21l5-5 4 5h10l5-13 6 29 6-34 6 25 5-7h17l5-6 5 6h13l5-10 5 17 5-7h7" stroke="var(--color-${color})" stroke-width="1.8" fill="none"/>`:type==='bars'?vals.map((n,i)=>`<rect x="${i*11}" y="${42-n*.7}" width="5" height="${n*.7}" rx="2" fill="var(--color-${color})" opacity="${.35+i*.05}"/>`).join(''):type==='area'?`<defs><linearGradient id="stepfill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--color-${color})" stop-opacity=".65"/><stop offset="1" stop-color="var(--color-${color})" stop-opacity=".02"/></linearGradient></defs><path d="M0 36Q14 37 23 21T47 20T72 23T97 14T130 9V42H0Z" fill="url(#stepfill)"/><path d="M0 36Q14 37 23 21T47 20T72 23T97 14T130 9" fill="none" stroke="var(--color-${color})" stroke-width="2"/>`:`<path d="M1 6 13 8 25 5 36 17 49 14 61 22 74 18 87 29 101 25 114 33 129 31" fill="none" stroke="var(--color-${color})" stroke-width="2" stroke-linejoin="round"/>`}</svg>`}
function metricCard(label,value,unit,color,type,action,change,status){return `<button class="metric-card tone-${color}" onclick="${esc(action)}"><span class="metric-label"><i class="metric-icon ${color}">${icon(label==='Heart rate'?'heart':label==='Weight'?'weight':label==='Calories'?'flame':'activity')}</i>${t(label)}</span><div class="metric-number">${value}<small>${unit}</small></div>${miniChart(type,color)}<div class="metric-bottom"><span>${change}</span><small>${t(status)}</small></div></button>`}
function imageWorkout(label='Full body flow',action="go('workout','Full body flow')",cls=''){return `<button class="image-workout ${cls}" onclick="${esc(action)}"><div class="image-workout-photo" style="view-transition-name:workout-photo">${img(photo,'Woman stretching in sunlight','',true)}</div><span class="image-kicker">${icon('dumbbell')} ${t('YOUR DAILY RESET')}</span><div class="workout-glass glass"><div><h3 style="view-transition-name:workout-title">${t(label)}</h3><p>${nf(state.duration)} ${t('min')} · ${t(state.experience)}</p></div><span class="round-start">${icon('play')}</span></div></button>`}
function progressCards(){return `<div class="progress-grid">${[['Total workout',nf(state.workouts.length),'dumbbell','trainingHistory'],['Training time',nf(workoutMinutes())+' '+t('min'),'clock','trainingHistory'],['Calories',nf(energy(workoutEnergy()))+' '+energyUnit(),'flame','activity'],['Streak',nf(7)+' '+t('days'),'trophy','streak']].map(([l,v,i,p])=>`<button class="progress-tile" onclick="go('${p}')">${icon(i)}<span>${t(l)}</span><strong>${v}</strong></button>`).join('')}</div>`}
function recommendations(){return `<div class="recommendation-track">${[['Training','A little stronger','Make 20 minutes your own.',photo,"go('workout','Full body flow')"],['Nutrition','Colour your plate','Find a little balance.',foodPhoto,"go('article','1')"],['Recovery','Room to recover','Let your body reset.',yogaPhoto,"go('article','0')"],['Mental wellness','A moment for you','Pause. Breathe. Begin again.',orb,"go('article','4')"]].map(([category,title,body,src,action])=>`<button class="recommendation" onclick="${esc(action)}">${img(src,title)}<div><span class="eyebrow">${t(category)}</span><h3>${t(title)}</h3><p>${t(body)}</p>${icon('arrow')}</div></button>`).join('')}</div>`}
screens.home=()=>`<header class="dashboard-header home-header"><button class="identity-button" onclick="nav('profile')">${img('assets/avatar.webp',state.name,'avatar home-portrait',true)}<span class="greeting">${t('Good morning,')}</span></button><div class="row">${ib('search',"go('search')",'Search')}${ib('bell',"go('messages')",'Notifications')}</div></header><div class="daily-heading"><div><span class="date-line">${df(undefined,{weekday:'short',day:'numeric',month:'short'})}</span><h1>${t('Feel good. Live better.')}</h1></div><button class="streak-chip" onclick="go('streak')">${icon('flame')}<b>${nf(7)}</b></button></div>${wellnessHero()}${analytics()}${section('Your daily signals','See all',"go('data')")}<div class="metric-grid">${metricCard('Heart rate',nf(state.hearts[0]?.value||68),'bpm','coral','wave',"go('heart')",'−2 bpm','Resting')}${metricCard('Steps',nf(6248),t('steps'),'orange','area',"go('activity','Steps')",'+12%','vs yesterday')}${metricCard('Calories',nf(energy(284+workoutEnergy())),energyUnit(),'health','bars',"go('activity','Calories')",'+8%','vs yesterday')}${metricCard('Weight',weight(state.weight),state.unit==='metric'?'kg':'lb','accent','line',"go('body')",'−'+nf(state.unit==='metric'?.6:1.3)+' '+(state.unit==='metric'?'kg':'lb'),'this week')}</div>${section('Today’s Plan','View plan',"nav('plan')")}${imageWorkout()}${section('Your Progress','Weekly progress',"go('review')")}${progressCards()}${section('AI Recommendations','See all',"go('aiCoach')")}${recommendations()}<button class="weekly-report-row" onclick="go('report')"><span class="list-icon">${icon('plan')}</span><span><b>${t('Weekly Health Report')}</b><small>${t('Small steps. Real progress.')}</small></span>${icon('arrow')}</button>${healthNote()}`;
screens.wellness=()=>header('Global Wellness',ib('plan',"go('calendar')",'Daily records'))+wellnessHero(true)+tabs(['Day','Week','Month'],period,'setPeriod')+`<div class="wellness-activity"><span class="eyebrow">${t('Physical Activity')}</span><div class="row between"><h2>${t('A stronger daily rhythm')}</h2><strong>${nf(80)}%</strong></div><div class="mini-stats"><div><strong>${nf(6248)}</strong><small>${t('Steps')}</small></div><div><strong>${nf(energy(284+workoutEnergy()))}</strong><small>${energyUnit()}</small></div><div><strong>${nf(32+workoutMinutes())}</strong><small>${t('Active minutes')}</small></div></div>${chart(period==='Day'?[21,34,43,35,62,75,82]:period==='Month'?[42,54,61,70,68,79,82]:[54,68,62,75,70,80,82],true)}</div><div class="card mt">${row('How your score works','Movement, recovery and consistency','leaf',"go('scoreInfo')")}${row('Edit daily goals','','settings',"go('goals')")}${row('Heart rate history','','heart',"go('history')")}${row('Daily records','','plan',"go('calendar')")}</div>${healthNote()}`;
screens.aiCoach=()=>header('AI Recommendations')+`<div class="ai-coach-hero glass">${aiOrb()}<span class="eyebrow">PULSEFIT AI</span><h2>${t('A little insight.<br>A healthier rhythm.')}</h2><p>${t('Suggestions shaped around your daily balance.')}</p>${badge('Personalised for you','leaf')}</div>${recommendations()}<div class="card mt">${row('Review your weekly rhythm','See your progress and next steps','activity',"go('report')")}${row('Make your plan fit you','Adjust days, duration and intensity','settings',"go('adjust')")}</div>${healthNote()}`;
function renderDesktop(){document.querySelector('.studio').innerHTML=`<a class="wordmark" href="#home" onclick="event.preventDefault();nav('home')"><span class="brand-icon">${icon('activity')}</span>PulseFit<span class="tiny">®</span></a><div class="studio-bottom">${themeControl('desktop')}<span class="eyebrow">${t('A LITTLE EVERY DAY.')}</span><h1>${t('Find your<br>healthy rhythm.')}</h1><p>${t('A little movement.<br>A little more you.')}</p><div class="studio-line"></div><span class="tiny">${t('INTERACTIVE APP CONCEPT')} &nbsp; / &nbsp; 2026</span></div>`;document.querySelector('.notes').innerHTML=`<div class="desktop-orb">${aiOrb()}</div><span class="eyebrow">${t('WELLBEING, REIMAGINED')}</span>${[['01','Move with purpose.','Build your rhythm.'],['02','Know your body.','Find your balance.'],['03','Grow together.','Feel the difference.']].map(([n,a,b])=>`<div class="note"><span>${n}</span><p>${t(a)}<br><strong>${t(b)}</strong></p></div>`).join('')}<p class="demo-note">${t('Interactive prototype · Simulated data')}<br>${t('No real payments or health readings')}</p>${btn('Explore onboarding',"go('welcome')",'text-button')}`}
render=function(){clearInterval(timer);timer=null;const d=document.querySelector('.device'),app=document.getElementById('app'),navEl=document.getElementById('nav');d.classList.toggle('dark',state.theme==='dark');document.documentElement.lang=PF_I18N.locale(state.lang);const primary=['home','plan','community','profile'].includes(page);d.dataset.page=page;app.classList.toggle('has-nav',primary);navEl.style.display=primary?'grid':'none';if(!navEl.querySelector('.nav-indicator'))navEl.innerHTML=`<div class="nav-indicator"></div>${['home','plan','community','profile'].map(x=>`<button data-tab="${x}" onclick="nav('${x}')"><span class="nav-icon">${icon(x)}</span><span class="nav-label"></span></button>`).join('')}`;['home','plan','community','profile'].forEach((x,i)=>{let b=navEl.querySelector(`[data-tab="${x}"]`);b.classList.toggle('active',x===page);b.setAttribute('aria-label',t(x[0].toUpperCase()+x.slice(1)));b.setAttribute('aria-current',x===page?'page':'false');b.querySelector('.nav-label').textContent=t(x[0].toUpperCase()+x.slice(1));if(x===page)navEl.style.setProperty('--active-index',i)});app.innerHTML=`<div class="page">${(screens[page]||screens.home)()}</div>`;renderDesktop();PF_I18N.localize(app,state.lang);afterRender();};
// More redesigned routes and motion are appended below.
const weekdays=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
function calendarStrip(){return `<div class="calendar-strip" style="--selected-day:${selectedDay}"><span class="calendar-indicator"></span>${weekdays.map((d,i)=>`<button class="${i===selectedDay?'active':''}" onclick="selectPlanDay(${i})" aria-label="${esc(t(d))}" aria-pressed="${i===selectedDay}"><span>${df(new Date(2026,8,14+i),{weekday:'short'})}</span><strong>${nf(14+i)}</strong><i class="${i<3?'complete':''}">${i<3?'✓':'·'}</i></button>`).join('')}</div>`}
const planTasks=[{name:'Full body flow',time:'08:00',duration:20,icon:'dumbbell',route:'workout'},{name:'Hydration check-in',time:'12:30',duration:2,icon:'activity',route:'task'},{name:'Evening wind-down',time:'18:00',duration:10,icon:'leaf',route:'workout'}];
function taskTimeline(){return `<div class="task-timeline">${planTasks.map((task,i)=>{const status=state.tasks?.[`${selectedDay}:${task.name}`]||state.tasks?.[task.name];return `<article class="timeline-item ${status===true?'task-done':status==='skipped'?'task-skipped':''}" data-task="${i}"><span class="task-time">${task.time}</span><span class="timeline-dot"></span><div class="timeline-card"><div class="row between"><span class="task-icon">${icon(status===true?'check':task.icon)}</span>${ib('more',`taskMore(${i})`,'More')}</div><h3>${t(task.name)}</h3><div class="row between"><span class="task-duration">${nf(task.duration)} ${t('min')}</span><button class="task-start ${status===true?'finished':''}" onclick="${status===true?`setTaskStatus(${i},false)`:`go('${task.route}','${task.name}')`}">${status===true?icon('check')+' '+t('Finished'):status==='skipped'?t('Restart'):t('Start')+icon('play')}</button></div></div></article>`}).join('')}</div>`}
function planWeekly(){const count=Math.min(state.workouts.length+Object.values(state.tasks||{}).filter(x=>x===true).length,state.frequency);return `<div class="plan-weekly card"><div class="row between"><h3>${t('Weekly progress')}</h3><span>${nf(Math.round(count/state.frequency*100))}%</span></div><div class="bar"><span style="width:${count/state.frequency*100}%"></span></div><div class="mini-stats"><div><strong>${nf(workoutMinutes())}</strong><small>${t('Training time')}</small></div><div><strong>${nf(state.workouts.length*5)}</strong><small>${t('Total volume')}</small></div><div><strong>${nf(85)}%</strong><small>${t('Recovery')}</small></div></div></div>`}
screens.plan=()=>state.planStatus==='deleted'?legacyScreens.plan():`${topHeader('Your plan','MOVE WITH INTENTION',ib('settings',"go('planSettings')",'Plan settings'))}<div class="plan-month row between"><span>${df(undefined,{month:'long',year:'numeric'})}</span>${btn('Full plan',"go('fullPlan')",'text-button')}</div>${calendarStrip()}<button class="plan-banner" onclick="go('fullPlan')">${img('assets/workout.webp','Your balanced training programme','',true)}<div class="plan-banner-shade"></div><div class="plan-banner-copy"><span class="image-kicker">${t('WEEK 2 OF 4')}</span><h2>${t('Build your<br>balance.')}</h2><p>${t(state.goal)} · ${nf(state.frequency)} ${t('days per week')}</p><span class="plan-banner-link">${t('Explore your plan')} ${icon('arrow')}</span></div></button>${state.workoutDraft?`<div class="resume-card glass"><h3>${t('Pick up where you left off')}</h3>${btn('Resume workout',"workIndex=state.workoutDraft.index;seconds=state.workoutDraft.seconds;rest=state.workoutDraft.rest;paused=false;go('player')",'primary mt')}</div>`:''}<div class="section-head"><h3 id="today-tasks-title">${t('Today’s rhythm')}</h3>${btn('View daily routine',"go('dayPlan',String(selectedDay))",'text-button')}</div><div id="timeline-holder">${taskTimeline()}</div><div id="weekly-holder">${planWeekly()}</div><div class="row mt">${btn('Adjust plan',"go('adjust')",'secondary')}${btn('Weekly review',"go('review')",'secondary')}</div>${section('Find your next favourite')}<div class="library-track"><button class="library-image-card" onclick="filter='All';go('library')">${img('assets/core-training.webp','Workout library')}<div><span>${t('Workout library')}</span>${icon('arrow')}</div></button><button class="library-image-card" onclick="go('movements')">${img(yogaPhoto,'Movement library')}<div><span>${t('Movement library')}</span>${icon('arrow')}</div></button></div>`;
function selectPlanDay(i){selectedDay=i;const strip=document.querySelector('.calendar-strip');if(!strip){render();return}strip.style.setProperty('--selected-day',i);strip.querySelectorAll('button').forEach((el,j)=>{el.classList.toggle('active',i===j);el.setAttribute('aria-pressed',String(i===j))});document.getElementById('today-tasks-title').textContent=t(weekdays[i]);const holder=document.getElementById('timeline-holder');holder.animate([{opacity:0,transform:'translateX(10px)'},{opacity:1,transform:'translateX(0)'}],{duration:reduced()?0:220,easing:'ease-out'});holder.innerHTML=taskTimeline();PF_I18N.localize(holder,state.lang)}
function taskMore(i){const task=planTasks[i];sheet(task.name,'Make this task work for your day.',btn('Mark complete',`closeSheet();setTaskStatus(${i},true)`)+btn('Skip today',`closeSheet();setTaskStatus(${i},'skipped')`,'secondary')+btn('Change time',`closeSheet();go('task','${task.name}')`,'secondary')+btn('Replace task',"closeSheet();go('library')",'secondary'))}
function setTaskStatus(i,status){state.tasks={...state.tasks,[`${selectedDay}:${planTasks[i].name}`]:status};save();const old=document.querySelector(`[data-task="${i}"]`);if(old&&!reduced())old.animate([{transform:'scale(1)'},{transform:'scale(.98)'},{transform:'scale(1)'}],{duration:250});document.getElementById('timeline-holder').innerHTML=taskTimeline();document.getElementById('weekly-holder').innerHTML=planWeekly();toast(status===true?'Task completed':status==='skipped'?'Task skipped for today':'Task updated');animateData()}
// Image-led community, preserving the existing posts, reactions, privacy and publish flow.
seededPosts[0].gallery=[runPhoto,yogaPhoto];seededPosts[1].gallery=['assets/workout.webp'];
const feedPhoto=p=>p.id==='s1'?runPhoto:p.id==='s2'?photo:p.image&&p.image!==true?p.image:foodPhoto;
function stories(){return `<div class="stories"><button class="story" onclick="openComposer()"><span class="story-ring own">${person()}<i>${icon('plus')}</i></span><span>${t('Your moment')}</span></button>${seededPosts.map((p,i)=>`<button class="story" onclick="go('user','${p.id}')"><span class="story-ring">${img(i?photo:yogaPhoto,p.name,'story-face')}<i>${icon('check')}</i></span><span data-user-content>${p.name.split(' ')[0]}</span></button>`).join('')}<button class="story" onclick="go('topics')"><span class="story-ring topic-story">${icon('leaf')}</span><span>${t('Small steps')}</span></button><button class="story" onclick="go('challengeProgress')"><span class="story-ring challenge-story">${icon('trophy')}</span><span>${t('Your wins')}</span></button></div>`}
function challengeBanner(){return `<section class="challenge-banner"><div><span class="eyebrow">${t('BETTER, TOGETHER')}</span><h2>${t('7 days.<br>A stronger you.')}</h2><p>${nf(1248)} ${t('participants')} · ${nf(state.checkins)} / 7</p><button class="challenge-join" onclick="go('challenge')">${t(state.joined?'Check your progress':'Join challenge')} ${icon('arrow')}</button></div><div class="challenge-photo">${img(yogaPhoto,'Move together outdoors')}<span>${icon('trophy')}</span></div></section>`}
function v2Post(p,detail=false){const gallery=p.gallery||(p.image?[p.image===true?runPhoto:p.image]:p.id==='s2'?[photo]:[]);const own=state.posts.some(x=>x.id===p.id);return `<article class="social-post" data-post-id="${p.id}"><header class="post-head"><button class="post-person" onclick="go('user','${p.id}')">${p.id.startsWith('s')?`<span class="avatar photo-avatar">${img(p.id==='s1'?yogaPhoto:photo,p.name)}</span>`:person(p.name)}<span><strong data-user-content>${esc(p.name)}</strong><small><span data-user-content>${esc(p.location||t('Your community'))}</span> · ${t(p.time||'Just now')}</small></span></button>${ib('more',`postMenu('${p.id}')`,'More')}</header>${gallery.length?`<div class="post-gallery ${gallery.length>1?'collage':''}">${gallery.map((src,i)=>`<button onclick="openPhoto('${p.id}',${i})" aria-label="${esc(t('Expand photo'))}">${img(src,'Community movement photo')}${i===1?`<span class="photo-overlay">${icon('plus')} ${t('Good company')}</span>`:''}</button>`).join('')}</div>`:''}${p.workout?`<button class="shared-workout-card" onclick="go('trainingHistory')">${icon('check')}<span>${t('WORKOUT COMPLETE')}<strong>${t('Full body flow')}</strong></span><b>${nf(state.duration)} ${t('min')}</b></button>`:''}<p class="post-text" ${own?'data-user-content':''}>${own?esc(p.text):t(p.text)}</p><button class="text-button tag" onclick="go('topic','${esc(p.topic||'SmallSteps')}')">#${esc(p.topic||'SmallSteps')}</button><div class="post-actions"><button class="reaction ${state.likes[p.id]?'active':''}" onclick="like('${p.id}')" aria-label="${esc(t('Like post'))}" aria-pressed="${!!state.likes[p.id]}">${icon('heart')}<span>${nf((p.likes||0)+(state.likes[p.id]?1:0))}</span></button><button onclick="openComments('${p.id}')" aria-label="${esc(t('Comments'))}">${icon('message')}<span>${nf((state.comments[p.id]||[]).length)}</span></button><button onclick="share('Community post')" aria-label="${esc(t('Share'))}">${icon('share')}</button><button class="save-post ${state.favorites.includes('post:'+p.id)?'is-saved':''}" onclick="favorite('post:${p.id}')" aria-label="${esc(t('Save post'))}" aria-pressed="${state.favorites.includes('post:'+p.id)}">${icon('bookmark')}</button></div>${!detail?btn('View conversation',`go('post','${p.id}')`,'post-detail-link'):''}</article>`}
postCard=v2Post;
screens.community=()=>`${topHeader('Community','',ib('search',"go('search')",'Search')+ib('message',"go('messages')",'Messages'))}<div class="community-tabs" style="--tab-index:${['For You','Following','Challenges'].indexOf(communityTab)}"><span></span>${['For You','Following','Challenges'].map(x=>`<button class="${x===communityTab?'active':''}" onclick="changeCommunity('${x}')">${t(x)}</button>`).join('')}</div><div id="community-content">${communityBody()}</div><button class="community-fab" onclick="openComposer()" aria-label="${esc(t('New post'))}">${icon('plus')}</button>`;
