changeCommunity=function(tab){communityTab=tab;const holder=document.getElementById('community-content');if(!holder){render();return}document.querySelector('.community-tabs').style.setProperty('--tab-index',['For You','Following','Challenges'].indexOf(tab));document.querySelectorAll('.community-tabs button').forEach((b,i)=>b.classList.toggle('active',i===['For You','Following','Challenges'].indexOf(tab)));holder.innerHTML=communityBody();PF_I18N.localize(holder,state.lang);holder.animate([{opacity:.6,transform:'translateX(12px)'},{opacity:1,transform:'translateX(0)'}],{duration:reduced()?0:220,easing:'ease-out'})};
like=function(id){state.likes[id]=!state.likes[id];save();const p=allPosts().find(p=>p.id===id),el=document.querySelector(`[data-post-id="${id}"] .reaction`);if(el){el.classList.toggle('active',!!state.likes[id]);el.setAttribute('aria-pressed',String(!!state.likes[id]));el.querySelector('span').textContent=nf((p?.likes||0)+(state.likes[id]?1:0));if(!reduced())el.querySelector('svg').animate([{transform:'scale(1)'},{transform:'scale(1.28)'},{transform:'scale(1)'}],{duration:280,easing:'cubic-bezier(.34,1.38,.64,1)'})}else render()};
const oldFavorite=favorite;
favorite=function(id){const enabled=!state.favorites.includes(id);state.favorites=enabled?[...state.favorites,id]:state.favorites.filter(x=>x!==id);save();toast(enabled?'Saved to your favourites':'Removed from saved');if(id.startsWith('post:')){document.querySelectorAll(`[data-post-id="${id.slice(5)}"] .save-post`).forEach(el=>{el.classList.toggle('is-saved',enabled);el.setAttribute('aria-pressed',String(enabled))})}else{const btn=document.querySelector('.page-header button[aria-label="'+t('Save workout')+'"],.page-header button[aria-label="'+t('Save article')+'"],.page-header button[aria-label="'+t('Save movement')+'"]');btn?.classList.toggle('is-saved',enabled)}if(page==='favorites')render()};
function openComments(id){window.commentPostId=id;sheet('Conversation','A little encouragement goes a long way.',`<div class="sheet-comments" id="sheet-comments">${commentsHtml(id)}</div><label class="form-field"><span>${t('Your comment')}</span><input id="sheet-comment" placeholder="${esc(t('Leave a little encouragement…'))}" onkeydown="if(event.key==='Enter')submitSheetComment()"></label>${btn('Post comment','submitSheetComment()')}`)}
function commentsHtml(id){return (state.comments[id]||[]).map(c=>`<div class="comment-row">${person()}<div><b data-user-content>${esc(state.name)}</b><p data-user-content>${esc(c)}</p></div></div>`).join('')||`<div class="empty"><p>${t('Start a kind conversation.')}</p></div>`}
function submitSheetComment(){const value=val('sheet-comment').trim();if(!value){toast('Write something before posting');return}state.comments[window.commentPostId]=[...(state.comments[window.commentPostId]||[]),value];save();document.getElementById('sheet-comments').innerHTML=commentsHtml(window.commentPostId);document.getElementById('sheet-comment').value='';document.querySelectorAll(`[data-post-id="${window.commentPostId}"] .post-actions button:nth-child(2) span`).forEach(el=>el.textContent=nf(state.comments[window.commentPostId].length));toast('Comment added')}
