function openPhoto(id,index){const p=allPosts().find(p=>p.id===id),sources=p?.gallery||(p?.image?[p.image===true?runPhoto:p.image]:[photo]);const src=sources[index]||sources[0];window.currentPhoto={id,index};previousFocus=document.activeElement;document.getElementById('app').inert=true;document.getElementById('nav').inert=true;document.getElementById('overlay').innerHTML=`<div class="photo-viewer" role="dialog" aria-modal="true" aria-label="${esc(t('Photo preview'))}"><header>${ib('close','closeSheet()','Close')}<span>${nf(index+1)} / ${nf(sources.length)}</span>${ib('share',"share('Community post')",'Share')}</header>${img(src,'Community movement photo','full-photo',true)}<p data-user-content>${esc(p?.name||'PulseFit')}</p>${sources.length>1?`<div class="photo-pager">${sources.map((x,i)=>btn(String(i+1),`openPhoto('${id}',${i})`,i===index?'primary':'secondary')).join('')}</div>`:''}</div>`;document.querySelector('.photo-viewer button').focus()}
