// Unified navigation motion: real shared-element snapshots when supported.
let transitionBusy=false,routeDirection='forward',activeViewTransition=null,lastToastKey='',sheetDrag=null;
function transitionRoute(change,kind='forward'){
 activeViewTransition?.skipTransition();transitionBusy=false;
 document.querySelectorAll('#app .page').forEach(el=>el.getAnimations().forEach(animation=>animation.cancel()));
 change();
 const content=document.querySelector('#app .page');
 if(content&&!reduced())content.animate([{opacity:.65},{opacity:1}],{duration:160,easing:'ease-out'});
}

go=function(p,arg=''){if(p==='language'){openLanguageSheet();return}if(p==='units'){openUnitsSheet();return}transitionRoute(()=>legacyGo(p,arg),'forward')};
nav=function(p){const tabs=['home','plan','community','profile'];if(p===page){document.getElementById('app').scrollTo({top:0,behavior:reduced()?'instant':'smooth'});return}const dir=tabs.indexOf(p)<tabs.indexOf(page)?'tab-left':'tab-right';transitionRoute(()=>legacyNav(p),dir)};
