// Keep native browser back history aligned with the navigation stack.
window.onpopstate=e=>{if(document.getElementById('overlay').innerHTML){closeSheet();return}const target=e.state?.page||decodeURIComponent(location.hash.slice(1)).split('=')[0]||'home';transitionRoute(()=>{const matching=prev.findLastIndex(x=>x.page===target);let restore=matching>=0?prev[matching]:{page:target,param:e.state?.param||'',scroll:scrolls[target]||0};if(matching>=0)prev=prev.slice(0,matching);page=screens[target]?target:'home';param=restore.param||'';render();document.getElementById('app').scrollTop=restore.scroll||0},'back')};
// Modal/sheet lifecycle, keyboard focus and touch dismissal.
sheet=function(title,body,actions){previousFocus=document.activeElement;const overlay=document.getElementById('overlay');document.getElementById('app').inert=true;document.getElementById('nav').inert=true;overlay.innerHTML=`<div class="scrim" onclick="if(event.target===this)closeSheet()"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(t(title))}"><div class="sheet-handle" aria-label="${esc(t('Drag down to close'))}"></div><div class="row between"><h2>${t(title)}</h2>${ib('close','closeSheet()','Close')}</div>${body?`<p>${t(body)}</p>`:''}${actions}</section></div>`;PF_I18N.localize(overlay,state.lang);bindSheetDismiss();requestAnimationFrame(()=>overlay.querySelector('button')?.focus())};
closeSheet=function(){const overlay=document.getElementById('overlay'),scrim=overlay.querySelector('.scrim'),panel=overlay.querySelector('.sheet,.photo-viewer');document.getElementById('app').inert=false;document.getElementById('nav').inert=false;const closingNode=overlay.firstElementChild;if(!closingNode)return;if(reduced()){closingNode.remove();previousFocus?.focus?.();return}scrim?.classList.add('closing');panel?.classList.add('closing');if(panel?.classList.contains('photo-viewer'))panel.animate([{opacity:1,transform:'scale(1)'},{opacity:0,transform:'scale(.96)'}],{duration:180,fill:'forwards'});closingNode.style.pointerEvents='none';setTimeout(()=>{if(closingNode.isConnected)closingNode.remove();previousFocus?.focus?.()},220)};
function bindSheetDismiss(){const panel=document.querySelector('.sheet'),handle=panel?.querySelector('.sheet-handle');if(!panel||!handle)return;handle.addEventListener('pointerdown',e=>{sheetDrag={y:e.clientY,pointer:e.pointerId};handle.setPointerCapture(e.pointerId)});handle.addEventListener('pointermove',e=>{if(!sheetDrag)return;const delta=Math.max(0,e.clientY-sheetDrag.y);panel.style.transform=`translateY(${delta}px)`});handle.addEventListener('pointerup',e=>{if(!sheetDrag)return;const delta=e.clientY-sheetDrag.y;sheetDrag=null;panel.style.transform='';if(delta>70)closeSheet()});}
document.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const dialog=document.querySelector('#overlay [role=dialog]');if(!dialog)return;const focusables=[...dialog.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);if(!focusables.length)return;if(e.shiftKey&&document.activeElement===focusables[0]){e.preventDefault();focusables.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===focusables.at(-1)){e.preventDefault();focusables[0].focus()}});
confirmAction=function(title,action){sheet(title,'This action changes your saved demo data.',btn('Confirm',`closeSheet();${action}`)+btn('Cancel','closeSheet()','secondary'));document.querySelector('.scrim').classList.add('modal-scrim');document.querySelector('.sheet').classList.add('center-modal')};
