function openLanguageSheet(){sheet('Language','Choose the language that feels like home.',`<div class="language-options">${Object.entries(PF_I18N.names).map(([code,label])=>`<button class="option ${state.lang===code?'selected':''}" onclick="setLanguage('${code}')" aria-pressed="${state.lang===code}"><span data-native-language>${label}</span><span class="check">${state.lang===code?'✓':''}</span></button>`).join('')}</div>${btn('Done','closeSheet()','primary mt')}`)}
function setLanguage(lang){if(!Object.hasOwn(PF_I18N.names,lang))return;const oldLang=state.lang;const values=[...document.querySelectorAll('#app input[id],#app textarea[id],#app select[id]')].map(el=>({id:el.id,value:el.value,checked:el.checked})),scroll=document.getElementById('app').scrollTop;state.lang=lang;save();render();values.forEach(v=>{const el=document.getElementById(v.id);if(el){el.value=v.value;if(el.type==='checkbox')el.checked=v.checked}});document.getElementById('app').scrollTop=scroll;const overlay=document.getElementById('overlay');if(overlay.querySelector('.language-options'))openLanguageSheet();else PF_I18N.localize(overlay,lang,oldLang);if(document.getElementById('toast').classList.contains('show'))document.getElementById('toast').textContent=t(lastToastKey);toast('Language updated')}
screens.language=()=>header('Language')+`<div class="language-options stack">${Object.entries(PF_I18N.names).map(([code,label])=>`<button class="option ${state.lang===code?'selected':''}" onclick="setLanguage('${code}')"><span data-native-language>${label}</span><span class="check">${state.lang===code?'✓':''}</span></button>`).join('')}</div>`;
function openUnitsSheet(){sheet('Your units','Your numbers, the way you know them.',`<div class="stack">${option('Metric',state.unit==='metric'?'Metric':'Imperial',"setUnit('metric')",'kg · cm · km · kcal')}${option('Imperial',state.unit==='imperial'?'Imperial':'Metric',"setUnit('imperial')",'lb · ft · mi · kJ')}</div>${select('Date format','dateformat',['DD/MM/YYYY','MM/DD/YYYY','YYYY-MM-DD'],state.dateformat||'DD/MM/YYYY')}${select('Time zone','timezone',['Europe/Amsterdam','Europe/Berlin','Europe/Paris','Europe/London','Asia/Shanghai','Asia/Tokyo'],state.timezone||'Europe/Amsterdam')}${btn('Save preferences',"state.dateformat=val('dateformat');state.timezone=val('timezone');save();closeSheet();render();toast('Preferences updated')",'primary mt')}`)}
function setUnit(unit){if(!['metric','imperial'].includes(unit))return;state.unit=unit;save();const pos=document.getElementById('app').scrollTop;render();document.getElementById('app').scrollTop=pos;openUnitsSheet()}
const animatedData=new Map();
function animateData(){const signature=page+':'+JSON.stringify([state.workouts.length,state.hearts.length,state.weight,state.tasks,state.lang]);if(animatedData.has(signature)||reduced())return;animatedData.set(signature,true);document.querySelectorAll('[data-count]').forEach(el=>{const target=+el.dataset.count,small=el.querySelector('small')?.outerHTML||'';let start=performance.now();const run=now=>{if(!el.isConnected)return;const p=Math.min(1,(now-start)/350),value=Math.round(target*(1-(1-p)**3));el.innerHTML=nf(value)+small;if(p<1)requestAnimationFrame(run)};requestAnimationFrame(run)});document.querySelectorAll('.wellness-ring circle').forEach(el=>el.animate([{strokeDashoffset:21.5,opacity:.3},{strokeDashoffset:0,opacity:1}],{duration:350,easing:'cubic-bezier(.22,1,.36,1)'}));document.querySelectorAll('.metric-chart path,.chart path[fill="none"]').forEach(el=>{if(!el.getTotalLength)return;const n=el.getTotalLength();el.animate([{strokeDasharray:n,strokeDashoffset:n},{strokeDasharray:n,strokeDashoffset:0}],{duration:340,easing:'ease-out'})});document.querySelectorAll('.metric-chart rect,.chart rect').forEach(el=>{el.style.transformOrigin='center bottom';el.style.transformBox='fill-box';el.animate([{transform:'scaleY(.05)'},{transform:'scaleY(1)'}],{duration:320,easing:'ease-out'})})}
function formatRecordDate(value,withTime=false){let d=new Date(value);if(Number.isNaN(+d)){const match=String(value).match(/(\d+) Sep(?:, (\d+):(\d+))?/);d=match?new Date(2026,8,+match[1],+(match[2]||12),+(match[3]||0)):new Date(2026,8,18)}return df(d,withTime?{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}:{day:'numeric',month:'short'})}
afterRender=function(){legacyAfter();document.documentElement.lang=PF_I18N.locale(state.lang);document.querySelectorAll('#app img').forEach(el=>{if(el.complete)el.classList.add('loaded')});const app=document.getElementById('app');app.onscroll=()=>app.querySelector('.dashboard-header')?.classList.toggle('scrolled',app.scrollTop>20);const scope=document.querySelector('#app .page');if(scope){scope.dataset.route=page;scope.classList.toggle('large-copy',state.textSize==='Large');if(page==='complete'||page==='paymentSuccess'||page==='published')scope.classList.add('success-page')}animateData();PF_I18N.localize(app,state.lang);if(page==='compose'&&state.selectedPostType)document.getElementById('posttype').value=state.selectedPostType;};
// Horizontal and downward touch gestures remain optional; buttons provide the same actions.
let touchOrigin=null;document.getElementById('app').addEventListener('touchstart',e=>{if(page==='community'&&document.getElementById('app').scrollTop<=1)touchOrigin=e.touches[0].clientY;},{passive:true});document.getElementById('app').addEventListener('touchend',e=>{if(touchOrigin!==null&&e.changedTouches[0].clientY-touchOrigin>85&&page==='community')refreshFeed();touchOrigin=null},{passive:true});
// Localised image export shares exactly the language visible in the interface.
downloadCard=function(title){const c=document.createElement('canvas');c.width=900;c.height=1100;const ctx=c.getContext('2d'),g=ctx.createLinearGradient(0,0,900,1100);g.addColorStop(0,'#5674FF');g.addColorStop(1,'#8B7CFF');ctx.fillStyle=g;ctx.fillRect(0,0,900,1100);ctx.fillStyle='#fff';ctx.font='600 31px Manrope, sans-serif';ctx.fillText('PULSEFIT',72,104);ctx.fillStyle='#ffffff26';ctx.beginPath();ctx.roundRect(48,175,804,830,44);ctx.fill();ctx.fillStyle='#fff';ctx.font='500 44px sans-serif';const wrap=(text,x,y,maxWidth,lineHeight)=>{let line='';for(const ch of [...text]){if(ctx.measureText(line+ch).width>maxWidth){ctx.fillText(line,x,y);line='';y+=lineHeight}line+=ch}ctx.fillText(line,x,y);return y};wrap(t(title),85,268,720,58);ctx.font='500 34px sans-serif';ctx.fillText(state.name,85,420);ctx.fillStyle='#D9FF63';ctx.font='500 112px Manrope, sans-serif';ctx.fillText(title.includes('certificate')?nf(7)+' / 7':title.includes('Heart')?nf(state.hearts[0]?.value||72):nf(score())+'%',85,635);ctx.fillStyle='#fff';ctx.font='30px sans-serif';wrap(t('Small steps. A lasting rhythm.'),85,786,720,44);ctx.font='23px sans-serif';ctx.fillText(t('Simulated demo data')+' · '+df(undefined,{month:'long',year:'numeric'}),85,952);const a=document.createElement('a');a.download='pulsefit-share.png';a.href=c.toDataURL('image/png');a.click();toast('Your image is ready')};
// Keep page chrome outside the scrolling content's visual rhythm.
const beforeChromeRender=afterRender;
afterRender=function(){
 chromeFooterObserver?.disconnect();
 document.getElementById('page-actions')?.remove();
 beforeChromeRender();
 const app=document.getElementById('app'),scope=app.querySelector('.page');
 document.querySelector('.device').classList.remove('chrome-scrolled');
 const heading=scope?.querySelector(':scope > .dashboard-header, :scope > .page-header');
 if(heading){
  heading.classList.add('scroll-header');
  const update=()=>{const compact=app.scrollTop>32;heading.classList.toggle('scrolled',compact);document.querySelector('.device').classList.toggle('chrome-scrolled',compact)};
  app.onscroll=update;update();requestAnimationFrame(update);
 }
 app.classList.remove('has-page-actions');app.style.removeProperty('--action-space');
 if(!app.classList.contains('has-nav')&&heading){
  const direct=[...scope.children],primary=direct.filter(el=>el.matches('button.primary'));
  let actions=[];
  if(page==='exercise')actions=direct.filter(el=>el.matches('button.secondary'));
  else if(primary.length){const main=primary.at(-1);actions=[main];let next=main.nextElementSibling;while(next?.matches('button.secondary,button.text-button')){actions.push(next);next=next.nextElementSibling}}
  if(actions.length){
   const footer=document.createElement('div');footer.id='page-actions';footer.className='page-actions';
   actions.forEach(el=>{el.classList.remove('mt');footer.append(el)});
   if(actions.length===2&&page==='exercise')footer.classList.add('paired-actions');
   document.querySelector('.device').append(footer);app.classList.add('has-page-actions');
   PF_I18N.localize(footer,state.lang);
   const size=()=>app.style.setProperty('--action-space',(footer.offsetHeight+24)+'px');size();
   chromeFooterObserver?.disconnect();chromeFooterObserver=new ResizeObserver(size);chromeFooterObserver.observe(footer);
  }
 }
};
let chromeFooterObserver=null;
new MutationObserver(()=>{const footer=document.getElementById('page-actions');if(footer)footer.inert=!!document.getElementById('overlay').children.length}).observe(document.getElementById('overlay'),{childList:true});
// Explicit demo session state. First-run setup is separate from plan editing.
paths.community='M4 3h13a3 3 0 0 1 3 3v6a3 3 0 0 1-3 3H9l-5 4V6a3 3 0 0 1 3-3M8 7h8M8 11h5M14 19h4l3 2v-6';
let setupStage=0;
const setupOrder=[1,4,0,2,3],originalOnboarding=screens.onboarding,originalOnboardNext=onboardNext;
startOnboarding=function(){flowMode='setup';setupStage=0;draftAnswers={...state,permissions:{...state.permissions},goal:state.goal||'Stay active'};go('intro')};
screens.intro=()=>header('Your personal plan')+`<section class="intro-coach"><div class="intro-coach-photo">${img(photo,'Movement in bright natural light','',true)}<span class="intro-coach-badge glass">${icon('leaf')} ${t('Personalised for you')}</span></div><h2>${t('Build a healthier<br>rhythm.')}</h2><p>${t('Bringing your goals, preferences and weekly routine together.')}</p><div class="intro-pill-row">${['Health profile','Privacy & permissions','Preferred movement'].map(x=>`<span>${t(x)}</span>`).join('')}</div></section>`+btn('Continue',"setupStage=0;go('onboarding')",'primary mt');
screens.onboarding=function(){if(flowMode!=='setup')return originalOnboarding();onboardStep=setupOrder[setupStage];let html=originalOnboarding();html=html.replace(/<p class="step-label">.*?<\/p>/,`<p class="step-label">${t('STEP')} ${setupStage+1} / 5</p>`).replace(/style="width:\d+%"/,`style="width:${(setupStage+1)*20}%"`);const start=html.indexOf('<div class="onboarding-bottom">');return html.slice(0,start)+`<div class="onboarding-bottom">${btn(setupStage===4?'Start my journey':'Next','onboardNext()')}${setupStage?btn('Previous step','setupStage--;render()','text-button'):''}</div>`};
onboardNext=function(){if(flowMode!=='setup')return originalOnboardNext();if(setupStage===0){let a=+val('age'),h=+val('height'),w=+val('weight'),tg=+val('target');if(draftAnswers.unit==='imperial'){h*=30.48;w/=2.20462;tg/=2.20462}if(a<18||a>100||h<100||h>240||w<30||w>300||tg<30||tg>300){document.getElementById('formerror').textContent=t('Check your age (18–100), height and weight.');return}Object.assign(draftAnswers,{age:a,height:h,weight:w,target:tg,gender:val('gender')})}if(setupStage===3)Object.assign(draftAnswers,{experience:val('experience'),duration:+val('duration'),equipment:val('equipment'),movement:val('movement'),injury:val('injury')});if(setupStage<4){setupStage++;render();document.getElementById('app').scrollTop=0}else{Object.assign(state,draftAnswers,{onboarded:true});save();flowMode='onboard';prev=[];nav('home');toast('Your new plan is ready')}};
function completeDemoLogin(){state.loggedIn=true;save();closeSheet();state.onboarded?nav('home'):startOnboarding()}
mockLogin=function(provider){sheet('Demo sign-in',`${provider} sign-in is simulated. No external account is connected.`,btn('Continue','completeDemoLogin()'))};
const profileSignedIn=screens.profile;
screens.profile=()=>{if(state.loggedIn)return profileSignedIn();return topHeader('My space','',ib('settings',"go('settings')",'Settings'))+`<section class="guest-profile card"><span class="guest-avatar">${icon('profile')}</span><h2>${t('Welcome back')}</h2><p>${t('Your next small step starts here.')}</p>${btn('Log in',"go('welcome')")}${btn('Create account',"go('register')",'secondary mt')}</section>`+section('Your preferences')+`<div class="card">${row('Language',PF_I18N.names[state.lang],'globe',"go('language')")}${row('Privacy & permissions','Your data, your choice','shield',"go('permissions')")}${row('Help & support','','message',"go('help')")}</div>`};
const welcomeWithProviders=screens.welcome;
screens.welcome=()=>welcomeWithProviders().replace(btn('Explore demo',"nav('home')",'text-button'),'').replace('<div class="welcome-actions">','<div class="welcome-actions">'+btn('Log in',"go('login')"));

// Content-bound images stay consistent between a card and its detail route.
const courseCovers={'Full body flow':photo,'Morning mobility':'assets/workout.webp','Evening wind-down':yogaPhoto,'Energising core':'assets/core-training.webp','Fresh air intervals':runPhoto};
const courseCover=name=>courseCovers[name]||photo;
paths.bell='M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4';
// Symmetric sliders are easier to recognise at small sizes than the old gear.
paths.settings='M4 7h4M12 7h8M4 17h8M16 17h4M8 4v6h4V4H8ZM12 14v6h4v-6h-4Z';
function openPlanPicker(id){const selectEl=document.getElementById(id);if(!selectEl)return;const title=selectEl.closest('.form-field').querySelector('span').textContent;sheet(title,'',`<div class="plan-picker-options" role="radiogroup" aria-label="${esc(title)}">${[...selectEl.options].map(o=>`<button class="option ${o.selected?'selected':''}" role="radio" aria-checked="${o.selected}" onclick="choosePlanOption('${id}','${esc(o.value)}')"><span>${esc(o.text)}</span><span class="check">${o.selected?icon('check'):''}</span></button>`).join('')}</div>`)}
function choosePlanOption(id,value){const field=document.getElementById(id);field.value=value;const trigger=document.querySelector(`[data-select-id="${id}"]`);trigger.querySelector('.picker-value').textContent=field.selectedOptions[0].text;trigger.setAttribute('aria-expanded','false');closeSheet();trigger.focus()}
const beforePickerRender=afterRender;
afterRender=function(){beforePickerRender();if(page!=='adjust')return;document.querySelectorAll('#app select').forEach(el=>{const label=el.closest('.form-field').querySelector('span');el.hidden=true;el.tabIndex=-1;const trigger=document.createElement('button');trigger.type='button';trigger.className='plan-picker-trigger';trigger.dataset.selectId=el.id;trigger.setAttribute('aria-label',label.textContent);trigger.setAttribute('aria-haspopup','dialog');trigger.setAttribute('aria-expanded','false');trigger.innerHTML=`<span class="picker-value">${esc(el.selectedOptions[0].text)}</span>${icon('chevron')}`;trigger.onclick=()=>{trigger.setAttribute('aria-expanded','true');openPlanPicker(el.id)};el.after(trigger)})};
const pickerClose=closeSheet;closeSheet=function(){document.querySelectorAll('.plan-picker-trigger').forEach(el=>el.setAttribute('aria-expanded','false'));pickerClose()};
const pickerLanguage=setLanguage;setLanguage=function(lang){pickerLanguage(lang);document.querySelectorAll('.plan-picker-trigger').forEach(el=>{el.querySelector('.picker-value').textContent=document.getElementById(el.dataset.selectId).selectedOptions[0].text})};
const detailWithCover=screens.workout;screens.workout=()=>detailWithCover().replace(`src="${photo}"`,`src="${courseCover(param||'Full body flow')}"`);
const exerciseWithCover=screens.exercise;screens.exercise=()=>exerciseWithCover().replace(`src="${photo}"`,`src="${[courseCovers['Morning mobility'],courseCovers['Energising core'],photo,courseCovers['Energising core'],yogaPhoto][+param||0]}"`);
// A single persisted preference drives the presentation canvas and the app.
paths.moon='M20.9 13.1A9 9 0 0 1 10.9 3.1 9 9 0 1 0 20.9 13.1Z';
function themeControl(location){return `<div class="theme-switch" data-theme-control="${location}" role="group" aria-label="${esc(t('Appearance'))}">${['light','dark'].map(mode=>`<button type="button" data-theme="${mode}" onclick="setTheme('${mode}')" aria-label="${esc(t(mode==='light'?'Light':'Dark'))}" aria-pressed="${state.theme===mode}" title="${esc(t(mode==='light'?'Light':'Dark'))}">${icon(mode==='light'?'sun':'moon')}${location==='desktop'?'':`<span>${t(mode==='light'?'Light':'Dark')}</span>`}</button>`).join('')}</div>`}
function syncTheme(){const dark=state.theme==='dark';document.documentElement.dataset.theme=dark?'dark':'light';document.querySelector('.device').classList.toggle('dark',dark);document.querySelectorAll('[data-theme-control] button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.theme===state.theme)));document.querySelector('meta[name="theme-color"]').content=dark?'#171b28':'#edf1fc'}
function setTheme(mode){if(!['light','dark'].includes(mode))return;state.theme=mode;save();syncTheme()}
const themeAfterRender=afterRender;afterRender=function(){themeAfterRender();syncTheme()};
const settingsBeforeTheme=screens.settings;screens.settings=()=>settingsBeforeTheme().replace(row('Appearance',state.theme==='dark'?'Dark':'Light','sun',"go('appearance')"),`<div class="settings-theme"><span>${t('Appearance')}</span>${themeControl('settings')}</div>`);
screens.appearance=()=>header('Appearance')+`<div class="card appearance-card">${themeControl('appearance')}</div>`+btn('Done','back()','primary mt');
const coverPreview=new URLSearchParams(location.search).get('cover')==='1';
page=coverPreview?'home':'login';param='';history.replaceState({page,param},'',coverPreview?'#home':'#login');render();
